//! Automatic conversation titles generated by an LLM.
//!
//! Runs once per conversation, right after the first completed run, and only
//! while the conversation still carries the first-message heuristic title.
//! The model is chosen from `user_preferences.title_model_id`, falling back
//! to the global default model.

use uuid::Uuid;

use crate::domain::{Conversation, Model};
use crate::error::{AppError, AppResult};
use crate::llm::{LlmMessage, NullCallbacks};
use crate::repo;
use crate::service::chat::provider_credentials;
use crate::state::AppState;

const TITLE_SYSTEM_PROMPT: &str = "Create a short title for the conversation below. \
Rules: 3 to 6 words, descriptive, no quotes, no trailing punctuation, and use the same \
language as the conversation. Reply with only the title.";

const USER_MAX_CHARS: usize = 1_500;
const ASSISTANT_MAX_CHARS: usize = 1_200;
const TITLE_MAX_CHARS: usize = 60;

/// Auto title pass: generate and persist a title if the conversation does not
/// have one yet.
pub async fn generate_for_conversation(
    state: &AppState,
    conversation_id: Uuid,
    user_id: Uuid,
) -> AppResult<()> {
    let conversation =
        repo::conversations::owned_by_id(&state.pool, conversation_id, user_id).await?;
    if conversation.title_generated {
        return Ok(());
    }
    let Some(model) = resolve_title_model(state, user_id).await? else {
        return Ok(());
    };
    let Some(title) = build_title(state, &conversation, &model).await? else {
        return Ok(());
    };
    repo::conversations::set_generated_title(&state.pool, conversation_id, &title).await?;
    Ok(())
}

/// Explicit (user-triggered) title generation: always replaces the current
/// title. Errors are surfaced so the UI can report them.
pub async fn generate_now(
    state: &AppState,
    conversation_id: Uuid,
    user_id: Uuid,
) -> AppResult<Conversation> {
    let conversation =
        repo::conversations::owned_by_id(&state.pool, conversation_id, user_id).await?;
    let model = resolve_title_model(state, user_id)
        .await?
        .ok_or_else(|| AppError::bad_request("no model configured for title generation"))?;
    let title = build_title(state, &conversation, &model)
        .await?
        .ok_or_else(|| AppError::bad_request("this conversation has no text to base a title on"))?;
    repo::conversations::rename(&state.pool, conversation_id, &title).await
}

/// Run the title prompt for one conversation. Returns `None` when there is no
/// usable user text or the model produced nothing.
async fn build_title(
    state: &AppState,
    conversation: &Conversation,
    model: &Model,
) -> AppResult<Option<String>> {
    let messages = repo::conversations::messages(&state.pool, conversation.id).await?;
    let user_text = messages
        .iter()
        .find(|m| m.role == "user")
        .map(|m| text_of(&m.parts))
        .unwrap_or_default();
    if user_text.trim().is_empty() {
        return Ok(None);
    }
    let assistant_text = messages
        .iter()
        .find(|m| m.role == "assistant")
        .map(|m| text_of(&m.parts))
        .unwrap_or_default();

    let mut excerpt = format!("User: {}\n", truncate(user_text.trim(), USER_MAX_CHARS));
    let assistant_excerpt = truncate(assistant_text.trim(), ASSISTANT_MAX_CHARS);
    if !assistant_excerpt.is_empty() {
        excerpt.push_str(&format!("Assistant: {assistant_excerpt}\n"));
    }

    let (provider, credentials) = provider_credentials(state, model).await?;
    let llm_messages = vec![
        LlmMessage::System {
            content: TITLE_SYSTEM_PROMPT.to_string(),
        },
        LlmMessage::User {
            content: excerpt,
            images: Vec::new(),
        },
    ];
    let mut callbacks = NullCallbacks;
    let outcome = provider
        .stream_chat(
            Uuid::new_v4(),
            &model.api_name,
            &llm_messages,
            &[],
            Some(0.3),
            // No cap: reasoning models spend completion tokens on reasoning
            // first, so a small max_tokens leaves the content empty.
            None,
            None,
            &credentials,
            &mut callbacks,
        )
        .await
        .map_err(|e| AppError::internal(format!("title generation failed: {e}")))?;

    if let (Some(prompt), Some(completion)) =
        (outcome.usage.prompt_tokens, outcome.usage.completion_tokens)
    {
        let _ = sqlx::query(
            "INSERT INTO usage_logs (user_id, conversation_id, model_id, prompt_tokens, completion_tokens) \
             VALUES ($1, $2, $3, $4, $5)",
        )
        .bind(conversation.user_id)
        .bind(conversation.id)
        .bind(model.id)
        .bind(prompt as i32)
        .bind(completion as i32)
        .execute(&state.pool)
        .await;
    }

    let title = clean_title(&outcome.text);
    if title.is_empty() {
        return Err(AppError::internal(
            "the title model returned an empty title (try a different model in Settings)",
        ));
    }
    Ok(Some(title))
}

/// The user's configured title model, or the global default model.
async fn resolve_title_model(state: &AppState, user_id: Uuid) -> AppResult<Option<Model>> {
    let configured: Option<Option<Uuid>> =
        sqlx::query_scalar("SELECT title_model_id FROM user_preferences WHERE user_id = $1")
            .bind(user_id)
            .fetch_optional(&state.pool)
            .await?;
    if let Some(Some(model_id)) = configured {
        if let Some(model) = repo::providers::model_by_id(&state.pool, model_id).await? {
            if model.status == "enabled" {
                return Ok(Some(model));
            }
        }
    }
    repo::providers::default_model(&state.pool).await
}

/// Concatenate the text parts of a stored message.
fn text_of(parts: &serde_json::Value) -> String {
    parts
        .as_array()
        .map(|arr| {
            arr.iter()
                .filter(|p| p.get("type").and_then(|v| v.as_str()) == Some("text"))
                .filter_map(|p| p.get("text").and_then(|v| v.as_str()))
                .collect::<Vec<_>>()
                .join("\n")
        })
        .unwrap_or_default()
}

fn truncate(s: &str, max: usize) -> String {
    s.chars().take(max).collect()
}

/// Normalize the model output into a single short title line.
fn clean_title(raw: &str) -> String {
    let first_line = raw
        .lines()
        .map(str::trim)
        .find(|line| !line.is_empty())
        .unwrap_or("");
    let trimmed = first_line
        .trim_matches(|c| matches!(c, '"' | '\'' | '“' | '”' | '‘' | '’'))
        .trim()
        .trim_end_matches(['.', ':', ';'])
        .trim();
    let total = trimmed.chars().count();
    let capped: String = trimmed.chars().take(TITLE_MAX_CHARS).collect();
    let capped = capped.trim();
    if capped.chars().count() == total {
        capped.to_string()
    } else {
        format!("{capped}…")
    }
}
